import {
  isNewerVersion,
  RUNTIME_UPGRADE_REQUIRED_MESSAGE,
} from './runtimeVersion';
import type { RuntimeActivity } from './runtimeActivity';

export type RuntimeRejection = {
  reason: 'server_retiring' | 'server_upgrade_required';
  error: string;
  serverVersion: string;
  clientVersion: string;
};

export class RuntimeAdmission {
  private isRetiring = false;
  private isShutdownRequested = false;
  private operations = 0;
  private requiredVersion: string;

  constructor(private readonly serverVersion: string) {
    this.requiredVersion = serverVersion;
  }

  observeClient(clientVersion: string): void {
    if (isNewerVersion(clientVersion, this.requiredVersion)) {
      this.requiredVersion = clientVersion;
    }
  }

  status() {
    const isDeferred = isNewerVersion(this.requiredVersion, this.serverVersion);
    let state: 'ready' | 'deferred' | 'retiring' = 'ready';
    if (isDeferred) state = 'deferred';
    if (this.isRetiring) state = 'retiring';
    return {
      state,
      serverVersion: this.serverVersion,
      clientVersion: this.requiredVersion,
      activeOperations: this.operations,
    };
  }

  enter({
    isGeneration,
    clientVersion,
  }: {
    isGeneration: boolean;
    clientVersion?: string;
  }): (() => void) | RuntimeRejection {
    if (clientVersion) this.observeClient(clientVersion);
    if (this.isRetiring) {
      return this.rejection(
        'server_retiring',
        'Rivet is restarting to apply an update. Retry after the editor reconnects. Your saved directions are preserved.',
      );
    }
    if (
      isGeneration &&
      isNewerVersion(this.requiredVersion, this.serverVersion)
    ) {
      return this.rejection(
        'server_upgrade_required',
        RUNTIME_UPGRADE_REQUIRED_MESSAGE,
      );
    }
    this.operations += 1;
    let isReleased = false;
    return () => {
      if (isReleased) return;
      isReleased = true;
      this.operations -= 1;
    };
  }

  beginRetirement(activity: RuntimeActivity, isForced = false): boolean {
    if (
      this.isRetiring ||
      (!isForced && (this.operations > 0 || activity !== 'idle'))
    )
      return false;
    this.isRetiring = true;
    return true;
  }

  cancelRetirement(): void {
    if (!this.isShutdownRequested) this.isRetiring = false;
  }

  beginShutdown(): void {
    this.isShutdownRequested = true;
    this.isRetiring = true;
  }

  private rejection(
    reason: RuntimeRejection['reason'],
    error: string,
  ): RuntimeRejection {
    return {
      reason,
      error,
      serverVersion: this.serverVersion,
      clientVersion: this.requiredVersion,
    };
  }
}
